'use client';

import { motion, type Transition } from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  GlobeIcon,
  LayersIcon,
  LinkIcon,
  LockIcon,
  UsersIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';

import { CopyButton } from './_parts/copy-button';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { PEOPLE, WORKSPACE_NAME } from './_parts/people';
import { PersonAvatar } from './_parts/person-avatar';
import {
  ACCESS_LEVELS,
  RoleSelect,
  type AccessLevel,
} from './_parts/role-select';
import { Swap } from './_parts/swap';

type GeneralAccess = 'invited' | 'workspace' | 'link';

type AccessOption = {
  value: GeneralAccess;
  label: string;
  line: string;
  icon: Icon;
};

const PROJECT_NAME = 'Atlas redesign';

const PROJECT_LINK = 'lattice.example/p/atlas-redesign';

const WORKSPACE_SIZE = 42;

const INVITED_PEOPLE = PEOPLE.slice(0, 6);

const SHOWN_AVATARS = 4;

const ACCESS_OPTIONS: AccessOption[] = [
  {
    value: 'invited',
    label: 'Only people invited',
    line: `${INVITED_PEOPLE.length} people can open it`,
    icon: LockIcon,
  },
  {
    value: 'workspace',
    label: `Everyone in ${WORKSPACE_NAME}`,
    line: `${WORKSPACE_SIZE} people in the workspace can open it`,
    icon: UsersIcon,
  },
  {
    value: 'link',
    label: 'Anyone with the link',
    line: 'Opens without signing in, so share it with care',
    icon: GlobeIcon,
  },
];

const TRAVEL: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const NO_TRAVEL: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return NO_TRAVEL;
  }
  return TRAVEL;
}

function isGeneralAccess(value: unknown): value is GeneralAccess {
  return ACCESS_OPTIONS.some((option) => option.value === value);
}

function audienceOf(access: GeneralAccess) {
  if (access === 'workspace') {
    return `Everyone in ${WORKSPACE_NAME}`;
  }
  if (access === 'link') {
    return 'Anyone with the link';
  }
  return 'Only people invited';
}

function AccessRow({
  option,
  isPicked,
  tintId,
}: {
  option: AccessOption;
  isPicked: boolean;
  tintId: string;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const OptionGlyph = option.icon;

  return (
    <label className='relative flex cursor-pointer items-center gap-3 rounded-lg px-3 py-2.5'>
      {isPicked && (
        <motion.span
          layoutId={tintId}
          aria-hidden='true'
          transition={travelOf(shouldReduceMotion)}
          className='bg-primary/[0.07] absolute inset-0 rounded-lg'
        />
      )}
      <span className='keycap-3d text-muted-foreground relative flex size-8 shrink-0 items-center justify-center rounded-lg'>
        <OptionGlyph className='size-4' />
      </span>
      <span className='relative flex min-w-0 flex-1 flex-col gap-0.5'>
        <span className='text-[13px] font-medium'>{option.label}</span>
        <span className='text-muted-foreground text-xs'>{option.line}</span>
      </span>
      <RadioGroupItem value={option.value} className='relative' />
    </label>
  );
}

function PeopleWithAccess() {
  const shown = INVITED_PEOPLE.slice(0, SHOWN_AVATARS);
  const hiddenCount = INVITED_PEOPLE.length - SHOWN_AVATARS;
  const hasHidden = hiddenCount > 0;
  const [first, second] = INVITED_PEOPLE;
  const othersCount = INVITED_PEOPLE.length - 2;

  return (
    <div className='flex items-center gap-3'>
      <div className='flex -space-x-2'>
        {shown.map((person) => (
          <PersonAvatar
            key={person.id}
            person={person}
            size='sm'
            className='ring-popover rounded-full ring-2'
          />
        ))}
        {hasHidden && (
          <span className='keycap-3d text-muted-foreground ring-popover relative flex size-6 items-center justify-center rounded-full text-[10px] font-medium tabular-nums ring-2'>
            {`+${hiddenCount}`}
          </span>
        )}
      </div>
      <p className='text-muted-foreground min-w-0 text-xs'>
        {`${first.name}, ${second.name} and ${othersCount} others were invited`}
      </p>
    </div>
  );
}

function ShareProject() {
  const [access, setAccess] = useState<GeneralAccess>('invited');
  const [linkLevel, setLinkLevel] = useState<AccessLevel>('view');
  const tintId = useId();
  const groupLabelId = useId();
  const isOpenBeyondInvites = access !== 'invited';
  const audience = audienceOf(access);
  const linkLevels = ACCESS_LEVELS.filter((level) => level.value !== 'manage');

  function changeAccess(value: unknown) {
    if (isGeneralAccess(value)) {
      setAccess(value);
    }
  }

  return (
    <>
      <div className='flex flex-col gap-3'>
        <span className='gem-plate flex size-10 items-center justify-center rounded-xl [--gem:var(--info)]'>
          <LayersIcon className='size-5' strokeWidth={2.25} />
        </span>
        <ModalHeader>
          <ModalTitle>{`Share ${PROJECT_NAME}`}</ModalTitle>
          <ModalDescription>
            Pick who can open the project, then send them the link
          </ModalDescription>
        </ModalHeader>
      </div>
      <div className='flex flex-col gap-2'>
        <p id={groupLabelId} className='text-[13px] font-medium'>
          Who can open it
        </p>
        <RadioGroup
          aria-labelledby={groupLabelId}
          value={access}
          onValueChange={changeAccess}
          className='bg-card hairline-ring ring-border gap-0 rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
        >
          {ACCESS_OPTIONS.map((option) => (
            <AccessRow
              key={option.value}
              option={option}
              isPicked={option.value === access}
              tintId={tintId}
            />
          ))}
        </RadioGroup>
        <AnimatedSize>
          {isOpenBeyondInvites && (
            <div className='flex items-center justify-between gap-3 pt-1 pl-3'>
              <Swap
                swapKey={audience}
                kind='label'
                className='text-muted-foreground flex min-w-0 text-xs'
              >
                {`${audience} can`}
              </Swap>
              <RoleSelect
                label='What people who open the link can do'
                value={linkLevel}
                options={linkLevels}
                onValueChange={setLinkLevel}
              />
            </div>
          )}
        </AnimatedSize>
      </div>
      <div className='bg-foreground/[0.03] flex items-center gap-3 rounded-xl p-2 pl-3'>
        <LinkIcon className='text-muted-foreground size-4 shrink-0' />
        <p className='text-muted-foreground min-w-0 flex-1 truncate text-[13px]'>
          {PROJECT_LINK}
        </p>
        <CopyButton
          text={`https://${PROJECT_LINK}`}
          label='Copy link'
          announcement='Project link copied'
        />
      </div>
      <PeopleWithAccess />
      <ModalFooter>
        <ModalCloseButton>Done</ModalCloseButton>
      </ModalFooter>
    </>
  );
}

export default function Modal05() {
  return (
    <ModalPreview triggerLabel='Open the share dialog' size='md'>
      <ShareProject />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { CheckIcon, CopyIcon, LinkIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

const COPIED_RESET_MS = 1600;

/** Copies a text and says so for a moment. */
export function useCopy(text: string) {
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsCopied(false);
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  }

  return { isCopied, copy };
}

type CopyGlyph = 'copy' | 'link';

function glyphOf(isCopied: boolean, glyph: CopyGlyph) {
  if (isCopied) {
    return <CheckIcon className='text-success-foreground' />;
  }
  if (glyph === 'link') {
    return <LinkIcon />;
  }
  return <CopyIcon />;
}

function labelOf(isCopied: boolean, label: string, copiedLabel: string) {
  if (isCopied) {
    return copiedLabel;
  }
  return label;
}

type CopyButtonProps = Omit<ButtonProps, 'children' | 'onClick'> & {
  text: string;
  /** Visible label. Leave it out for an icon button, and give `aria-label` instead. */
  label?: string;
  copiedLabel?: string;
  /** Announced once the text is on the clipboard. */
  announcement: string;
  glyph?: CopyGlyph;
};

/** A copy action whose icon becomes a check and whose label becomes Copied, then returns. */
export function CopyButton({
  text,
  label,
  copiedLabel = 'Copied',
  announcement,
  glyph = 'copy',
  variant = 'outline',
  size = 'sm',
  ...props
}: CopyButtonProps) {
  const { isCopied, copy } = useCopy(text);
  const icon = glyphOf(isCopied, glyph);
  const iconKey = String(isCopied);
  const hasLabel = Boolean(label);
  const shownLabel = labelOf(isCopied, label ?? '', copiedLabel);

  return (
    <>
      <Button variant={variant} size={size} onClick={copy} {...props}>
        <Swap swapKey={iconKey}>{icon}</Swap>
        {hasLabel && (
          <AnimatedSize axis='width' as='span'>
            <Swap swapKey={shownLabel} kind='label'>
              {shownLabel}
            </Swap>
          </AnimatedSize>
        )}
      </Button>
      <span className='sr-only' role='status'>
        {isCopied && announcement}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

